class webserviceActions extends sfActions
{
  public function executeIndex()
  {
    return $this->forward('webservice', 'list');
  }

  public function executeList()
  {
  	$c = new Criteria();  	
  	
  	$pager=new sfPropelPager('WsUsuarios',50);
	$pager->setCriteria($c);
	$pager->setPage($this->getRequestParameter('page',1));
	$pager->init();
	$this->pager=$pager;
	
    //$this->ws_usuarioss = WsUsuariosPeer::doSelect(new Criteria());
  }

  public function executeShow()
  {
    $this->ws_usuarios = WsUsuariosPeer::retrieveByPk($this->getRequestParameter('wsusuarios_id'));
    $this->forward404Unless($this->ws_usuarios);
  }

  public function executeCreate()
  {
    $this->ws_usuarios = new WsUsuarios();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    $this->ws_usuarios = WsUsuariosPeer::retrieveByPk($this->getRequestParameter('wsusuarios_id'));
    $this->forward404Unless($this->ws_usuarios);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('wsusuarios_id'))
    {
      $ws_usuarios = new WsUsuarios();
    }
    else
    {
      $ws_usuarios = WsUsuariosPeer::retrieveByPk($this->getRequestParameter('wsusuarios_id'));
      $this->forward404Unless($ws_usuarios);
    }

    $ws_usuarios->setWsusuariosId($this->getRequestParameter('wsusuarios_id'));
    $ws_usuarios->setUsuario($this->getRequestParameter('usuario'));
    $ws_usuarios->setPassword(md5($this->getRequestParameter('password')));
    $ws_usuarios->setNombre($this->getRequestParameter('nombre'));
    $ws_usuarios->setDireccion($this->getRequestParameter('direccion'));
    $ws_usuarios->setTelefono($this->getRequestParameter('telefono'));
    $ws_usuarios->setEmail($this->getRequestParameter('email'));

    $ws_usuarios->save();

    return $this->redirect($this->getRequest()->getScriptName().'/webservice/list');
  }

  public function executeDelete()
  {
    $ws_usuarios = WsUsuariosPeer::retrieveByPk($this->getRequestParameter('wsusuarios_id'));

    $this->forward404Unless($ws_usuarios);

    $ws_usuarios->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/webservice/list');
  }
}
